  });

  it("rejects an oversized broker response", async () => {
    const { env } = createEnv({
      response: new Response("x".repeat(64 * 1024 + 1), { status: 200 }),
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toThrow(
      "invalid token response",
